    return None if dp[target]==float('inf') else dp[target]

def solve(program,limit):
    r={'x':0,'y':0};pc=0;steps=0
    while 0<=pc<len(program) and steps<limit:
        ins=program[pc];steps+=1
        if ins[0]=='halt':return dict(registers=r,pc=pc,steps=steps,status='halted')
        if ins[0]=='set':r[ins[1]]=ins[2]
        if ins[0]=='add':r[ins[1]]+=ins[2]
        pc=ins[2] if ins[0]=='jnz' and r[ins[1]] else pc+1
    return dict(registers=r,pc=pc,steps=steps,status='exited' if not 0<=pc<len(program) else 'limited')

def solve(proposers,receivers):
    rank={r:{p:i for i,p in enumerate(ps)} for r,ps in receivers.items()}
    free=set(proposers);held={};next_choice=dict.fromkeys(proposers,0)
    while free:
        p=min(free);free.remove(p);r=proposers[p][next_choice[p]];next_choice[p]+=1
        if r not in held:held[r]=p
        elif rank[r][p]<rank[r][held[r]]:free.add(held[r]);held[r]=p
        else:free.add(p)
    return {p:r for r,p in held.items()}
